<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, useId } from 'vue'
import { COMMON_COUNTRY_CODES, findCountry, searchCountries } from '@/utils/countries'
const props=withDefaults(defineProps<{modelValue?:string|null;selected?:string[];multiple?:boolean;disabled?:boolean;placeholder?:string;label?:string;clearable?:boolean}>(),{selected:()=>[],placeholder:'请选择国家',label:'国家',clearable:true})
const emit=defineEmits<{'update:modelValue':[value:string];'update:selected':[value:string[]]}>()
const root=ref<HTMLElement>(),trigger=ref<HTMLButtonElement>(),panel=ref<HTMLElement>(),searchInput=ref<HTMLInputElement>()
const open=ref(false),search=ref(''),active=ref(0),position=ref({left:'0px',top:'0px',width:'360px',maxHeight:'360px'}),listId=useId()
const selectedCountry=computed(()=>findCountry(props.modelValue))
const matches=computed(()=>searchCountries(search.value))
const shortcuts=computed(()=>[...new Set([...COMMON_COUNTRY_CODES,...props.selected])].map(findCountry).filter(c=>!!c))
function choose(code:string){if(props.disabled)return;if(props.multiple)emit('update:selected',props.selected.includes(code)?props.selected.filter(c=>c!==code):[...props.selected,code]);else{emit('update:modelValue',code);close(true)}}
async function toggle(){if(props.disabled)return;if(open.value){close();return}const rect=trigger.value!.getBoundingClientRect();const width=Math.min(380,window.innerWidth-24),below=window.innerHeight-rect.bottom-12,above=rect.top-12,up=below<240&&above>below,height=Math.min(370,up?above:below);position.value={left:`${Math.max(12,Math.min(rect.left,window.innerWidth-width-12))}px`,top:`${up?Math.max(12,rect.top-height-6):rect.bottom+6}px`,width:`${width}px`,maxHeight:`${Math.max(120,height)}px`};open.value=true;search.value='';active.value=0;await nextTick();searchInput.value?.focus()}
function close(focus=false){open.value=false;if(focus)trigger.value?.focus()}
function outside(event:PointerEvent){if(!root.value?.contains(event.target as Node)&&!panel.value?.contains(event.target as Node))close()}
function onScroll(event:Event){if(open.value&&!panel.value?.contains(event.target as Node))close()}
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true)}else if(event.target!==searchInput.value){return}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();active.value=Math.max(0,Math.min(matches.value.length-1,active.value+(event.key==='ArrowDown'?1:-1)));void nextTick(()=>panel.value?.querySelector(`[data-index="${active.value}"]`)?.scrollIntoView?.({block:'nearest'}))}else if(event.key==='Enter'){event.preventDefault();const item=matches.value[active.value];if(item)choose(item.code)}}
onMounted(()=>{document.addEventListener('pointerdown',outside);window.addEventListener('scroll',onScroll,true);window.addEventListener('resize',onScroll)})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside);window.removeEventListener('scroll',onScroll,true);window.removeEventListener('resize',onScroll)})
</script>
<template>
 <div ref="root" class="country-picker">
  <div v-if="multiple" class="country-shortcuts"><button v-for="country in shortcuts" :key="country.code" type="button" class="country-chip" :class="{chosen:selected.includes(country.code)}" :aria-label="`${country.name} ${country.code}`" :aria-pressed="selected.includes(country.code)" :title="country.name" :disabled="disabled" @click="choose(country.code)"><img :src="country.flagUrl" alt="" />{{country.code}}</button></div>
  <button ref="trigger" type="button" role="combobox" class="country-trigger input" :aria-label="label" :aria-expanded="open" :aria-controls="listId" aria-haspopup="listbox" :disabled="disabled" @click="toggle" @keydown.down.prevent="!open&&toggle()">
   <template v-if="multiple">更多国家</template><template v-else-if="selectedCountry"><img :src="selectedCountry.flagUrl" alt="" />{{selectedCountry.code}}</template><template v-else>{{modelValue||placeholder}}</template><span class="country-chevron" aria-hidden="true">⌄</span>
  </button>
  <Teleport to="body"><div v-if="open" ref="panel" class="country-popover" :style="position" @keydown="key">
   <input ref="searchInput" v-model="search" type="search" class="input country-search" placeholder="搜索二字码 / 中文名" aria-label="搜索国家" :aria-controls="listId" :aria-activedescendant="matches.length?`${listId}-${active}`:undefined" @input="active=0" />
   <div :id="listId" class="country-options" role="listbox" :aria-label="label" :aria-multiselectable="multiple||undefined">
    <button v-if="!multiple&&clearable&&!search" type="button" class="country-clear" @click="choose('')">{{placeholder}}</button>
    <button v-for="(country,index) in matches" :id="`${listId}-${index}`" :key="country.code" type="button" role="option" class="country-option" :data-index="index" :class="{focused:index===active}" :aria-label="`${country.name} ${country.code}`" :aria-selected="multiple?selected.includes(country.code):selectedCountry?.code===country.code" :title="country.name" @click="choose(country.code)"><img :src="country.flagUrl" alt="" /><span>{{country.code}}</span><span v-if="multiple&&selected.includes(country.code)" class="country-check">✓</span></button>
   </div><p v-if="!matches.length" class="country-empty">未找到匹配国家</p><div class="country-count">{{matches.length}} 个国家及地区</div>
  </div></Teleport>
 </div>
</template>
<style scoped>
.country-picker,.country-shortcuts{display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-width:0}.country-trigger{display:inline-flex;align-items:center;gap:8px;min-width:118px;width:auto;margin:0;cursor:pointer;text-align:left}.country-chevron{margin-left:auto;color:var(--color-text-secondary)}img{width:22px;height:16px;object-fit:cover;border-radius:2px;box-shadow:0 0 0 1px var(--color-border)}.country-chip{display:inline-flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid var(--color-border);border-radius:6px;background:var(--color-surface);color:var(--color-text-secondary);font-size:13px;cursor:pointer}.country-chip.chosen{background:var(--color-selection-bg);border-color:var(--color-selection-border);color:var(--color-primary)}.country-popover{position:fixed;z-index:220;display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-surface);color:var(--color-text);box-shadow:0 12px 36px #0002;box-sizing:border-box}.country-search{width:100%;margin:0;flex-shrink:0}.country-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;overflow-y:auto;min-height:0}.country-option{display:flex;align-items:center;gap:8px;background:transparent;border:1px solid transparent;color:var(--color-text);border-radius:5px;padding:8px;font-size:13px;cursor:pointer}.country-option:hover,.country-option.focused{background:var(--color-bg-subtle,var(--color-selection-bg))}.country-option[aria-selected=true]{border-color:var(--color-selection-border);background:var(--color-selection-bg);color:var(--color-primary)}.country-check{margin-left:auto}.country-clear{grid-column:1/-1;text-align:left;padding:8px;background:none;border:0;color:var(--color-text-secondary);cursor:pointer}.country-count,.country-empty{font-size:12px;color:var(--color-text-secondary);margin:0}.country-count{border-top:1px solid var(--color-border);padding-top:8px}button:focus-visible{outline:2px solid var(--color-primary);outline-offset:2px}button:disabled{opacity:.6;cursor:not-allowed}
</style>
